src/lib/TradingCallbacksLib.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import '@openzeppelin/contracts/utils/math/SafeCast.sol';
import '@openzeppelin/contracts/utils/math/SignedMath.sol';
import '@openzeppelin/contracts/utils/math/Math.sol';
import '../interfaces/IOstiumTradingStorage.sol';
import '../interfaces/IOstiumPairInfos.sol';
import '../interfaces/IOstiumRegistry.sol';
import '../interfaces/IOstiumVault.sol';
import '../interfaces/IOstiumPairsStorage.sol';
import '../interfaces/IOstiumTradingCallbacks.sol';

library TradingCallbacksLib {
    using SafeCast for uint256;
    using SafeCast for uint192;

    uint256 constant PRECISION_27 = 1e27;
    uint64 constant PRECISION_18 = 1e18;
    uint64 constant PRECISION_10 = 1e10;
    uint32 constant PRECISION_6 = 1e6;
    uint16 constant MAX_GAIN_P = 900; // 900% PnL (10x)
    uint64 constant MAX_DECAY_FACTOR = 3e18; // 18 decimals
    uint256 constant CLOSE_FEE_SCALE_FACTOR = 100e6;

    struct PriceImpactResult {
        uint256 priceImpactP;
        uint256 priceAfterImpact;
        bool isDynamic;
    }

    struct TradeValueResult {
        uint256 tradeValue;
        uint256 liqMarginValue;
        int256 rolloverFees;
        int256 fundingFees;
        int256 profitP;
    }

    function _getTradePriceImpact(int192 price, int192 ask, int192 bid, bool isOpen, bool isLong)
        internal
        pure
        returns (uint256 priceImpactP, uint256 priceAfterImpact)
    {
        if (price == 0) {
            return (0, 0);
        }
        bool aboveSpot = (isOpen == isLong);

        int192 usedPrice = aboveSpot ? ask : bid;

        priceImpactP = (SignedMath.abs(price - usedPrice) * PRECISION_18 * 100 / uint192(price));

        return (priceImpactP, uint192(usedPrice));
    }

    function _currentPercentProfit(
        int256 openPrice,
        int256 currentPrice,
        bool buy,
        int32 leverage,
        int32 initialLeverage
    ) internal pure returns (int256 p, int256 maxPnlP) {
        maxPnlP = int16(MAX_GAIN_P) * int32(PRECISION_6) * int256(leverage)
            / (leverage > initialLeverage ? leverage : initialLeverage);

        p = (buy ? currentPrice - openPrice : openPrice - currentPrice) * int32(PRECISION_6) * leverage / openPrice;

        p = p > maxPnlP ? maxPnlP : p;
    }

    function currentPercentProfit(
        int256 openPrice,
        int256 currentPrice,
        bool buy,
        int32 leverage,
        int32 initialLeverage
    ) public pure returns (int256 p, int256 maxPnlP) {
        return _currentPercentProfit(openPrice, currentPrice, buy, leverage, initialLeverage);
    }

    function correctTp(uint192 openPrice, uint192 tp, uint32 leverage, uint32 initialLeverage, bool buy)
        public
        pure
        returns (uint192)
    {
        (int256 p, int256 maxPnlP) =
            _currentPercentProfit(openPrice.toInt256(), tp.toInt256(), buy, int32(leverage), int32(initialLeverage));

        if (tp == 0 || p == maxPnlP) {
            uint256 tpDiff = (openPrice * SignedMath.abs(maxPnlP)) / PRECISION_6 / leverage;
            return (buy ? openPrice + tpDiff : (tpDiff <= openPrice ? openPrice - tpDiff : 0)).toUint192();
        }
        return tp;
    }

    function correctSl(uint192 openPrice, uint192 sl, uint32 leverage, uint32 initialLeverage, bool buy, uint8 maxSl_P)
        public
        pure
        returns (uint192)
    {
        (int256 p,) =
            _currentPercentProfit(openPrice.toInt256(), sl.toInt256(), buy, int32(leverage), int32(initialLeverage));
        if (sl > 0 && p < int8(maxSl_P) * int32(PRECISION_6) * -1) {
            uint256 slDiff = (openPrice * maxSl_P) / leverage;
            return (buy ? openPrice - slDiff : openPrice + slDiff).toUint192();
        }
        return sl;
    }

    function correctToNullSl(
        uint192 openPrice,
        uint192 sl,
        uint32 leverage,
        uint32 initialLeverage,
        bool buy,
        uint8 maxSl_P
    ) external pure returns (uint192) {
        (int256 p,) = _currentPercentProfit(
            openPrice.toInt256(), sl.toInt256(), buy, int32(leverage), int32(initialLeverage)
        );
        if (sl > 0 && p < int8(maxSl_P) * int32(PRECISION_6) * -1) {
            return 0;
        }
        return sl;
    }

    /// @notice Returns the effective max leverage for a trade based on whether it's a day trade or overnight trade
    /// @dev When overnightMaxLeverage is 0, all trades are overnight and use pairMaxLeverage
    ///      When overnightMaxLeverage > 0, day trades use pairMaxLeverage, overnight trades use overnightMaxLeverage
    /// @dev Duplicated in TradingLib, update it there as well.
    function getEffectiveMaxLeverage(uint16 pairIndex, bool isDayTrade, IOstiumPairsStorage pairsStorage)
        public
        view
        returns (uint32)
    {
        uint32 overnightMaxLeverage = pairsStorage.pairOvernightMaxLeverage(pairIndex);
        return isDayTrade
            ? pairsStorage.pairMaxLeverage(pairIndex)
            : (overnightMaxLeverage > 0 ? overnightMaxLeverage : pairsStorage.pairMaxLeverage(pairIndex));
    }

    function withinMaxLeverage(uint16 pairIndex, uint256 leverage, bool isDayTrade, IOstiumPairsStorage pairsStorage)
        public
        view
        returns (bool)
    {
        return leverage <= getEffectiveMaxLeverage(pairIndex, isDayTrade, pairsStorage);
    }

    function withinExposureLimits(
        uint16 pairIndex,
        bool buy,
        uint256 collateral,
        uint32 leverage,
        uint256 price,
        IOstiumPairsStorage pairsStorage,
        IOstiumTradingStorage tradingStorage
    ) public view returns (bool) {
        return tradingStorage.openInterest(pairIndex, buy ? 0 : 1) * price / PRECISION_18 / 1e12 + collateral * leverage
                    / 100 <= tradingStorage.openInterest(pairIndex, 2)
            && pairsStorage.groupCollateral(pairIndex, buy) + collateral <= pairsStorage.groupMaxCollateral(pairIndex);
    }

    function getTradeAndPriceData(
        IOstiumPriceUpKeep.PriceUpKeepAnswer calldata a,
        IOstiumTradingStorage.Trade calldata t,
        IOstiumPairInfos pairInfos,
        uint32 initialLeverage,
        uint32 maxLeverage,
        uint256 collateral,
        bool isMarketPrice
    ) external returns (TradeValueResult memory, PriceImpactResult memory) {
        PriceImpactResult memory result =
            getDynamicTradePriceImpact(a.price, a.ask, a.bid, false, t, pairInfos, collateral);

        (int256 profitP,) = currentPercentProfit(
            t.openPrice.toInt256(),
            isMarketPrice ? a.price : result.priceAfterImpact.toInt256(),
            t.buy,
            int32(t.leverage),
            int32(initialLeverage)
        );

        (uint256 tradeValue, uint256 liqMarginValue, int256 rolloverFees, int256 fundingFees) =
            pairInfos.getTradeValue(t.trader, t.pairIndex, t.index, t.buy, collateral, t.leverage, profitP, maxLeverage);

        return (
            TradeValueResult({
                tradeValue: tradeValue,
                liqMarginValue: liqMarginValue,
                rolloverFees: rolloverFees,
                fundingFees: fundingFees,
                profitP: profitP
            }),
            result
        );
    }

    function getOpenTradeMarketCancelReason(
        bool isPaused,
        uint256 wantedPrice,
        uint256 slippageP,
        uint192 a_price,
        IOstiumTradingStorage.Trade memory trade,
        uint256 priceImpactP,
        IOstiumPairInfos pairInfos,
        IOstiumPairsStorage pairsStorage,
        IOstiumTradingStorage tradingStorage
    ) external view returns (IOstiumTradingCallbacks.CancelReason) {
        uint256 maxSlippage = (wantedPrice * slippageP) / 100 / 100;

        if (isPaused) return IOstiumTradingCallbacks.CancelReason.PAUSED;

        // Check slippage
        if (trade.buy ? trade.openPrice > wantedPrice + maxSlippage : trade.openPrice < wantedPrice - maxSlippage) {
            return IOstiumTradingCallbacks.CancelReason.SLIPPAGE;
        }

        // Check if TP is reached
        if (trade.tp != 0 && (trade.buy ? trade.openPrice >= trade.tp : trade.openPrice <= trade.tp)) {
            return IOstiumTradingCallbacks.CancelReason.TP_REACHED;
        }

        // Check if SL is reached
        if (trade.sl != 0 && (trade.buy ? trade.openPrice <= trade.sl : trade.openPrice >= trade.sl)) {
            return IOstiumTradingCallbacks.CancelReason.SL_REACHED;
        }

        // Check exposure limits
        if (!withinExposureLimits(
                trade.pairIndex, trade.buy, trade.collateral, trade.leverage, a_price, pairsStorage, tradingStorage
            )) {
            return IOstiumTradingCallbacks.CancelReason.EXPOSURE_LIMITS;
        }

        // Check price impact
        if (priceImpactP * trade.leverage / 100 / PRECISION_18 > pairInfos.maxNegativePnlOnOpenP()) {
            return IOstiumTradingCallbacks.CancelReason.PRICE_IMPACT;
        }

        // Check max leverage
        if (!withinMaxLeverage(trade.pairIndex, trade.leverage, trade.isDayTrade, pairsStorage)) {
            return IOstiumTradingCallbacks.CancelReason.MAX_LEVERAGE;
        }

        return IOstiumTradingCallbacks.CancelReason.NONE;
    }

    function getAutomationOpenOrderCancelReason(
        IOstiumTradingStorage.OpenLimitOrder memory o,
        uint256 priceAfterImpact,
        uint256 a_price,
        uint256 priceImpactP,
        IOstiumPairInfos pairInfos,
        IOstiumPairsStorage pairsStorage,
        IOstiumTradingStorage tradingStorage
    ) external view returns (IOstiumTradingCallbacks.CancelReason) {
        // Check if price target is hit based on order type
        bool isNotHit = o.orderType == IOstiumTradingStorage.OpenOrderType.LIMIT
            ? (o.buy ? priceAfterImpact > o.targetPrice : priceAfterImpact < o.targetPrice)
            : (o.buy ? uint192(a_price) < o.targetPrice : uint192(a_price) > o.targetPrice);

        if (isNotHit) return IOstiumTradingCallbacks.CancelReason.NOT_HIT;

        // Check if TP is reached
        if (o.tp != 0 && (o.buy ? priceAfterImpact >= o.tp : priceAfterImpact <= o.tp)) {
            return IOstiumTradingCallbacks.CancelReason.TP_REACHED;
        }

        // Check if SL is reached
        if (o.sl != 0 && (o.buy ? priceAfterImpact <= o.sl : priceAfterImpact >= o.sl)) {
            return IOstiumTradingCallbacks.CancelReason.SL_REACHED;
        }

        // Check exposure limits
        if (!withinExposureLimits(
                o.pairIndex, o.buy, o.collateral, o.leverage, uint192(a_price), pairsStorage, tradingStorage
            )) {
            return IOstiumTradingCallbacks.CancelReason.EXPOSURE_LIMITS;
        }

        // Check price impact
        if (priceImpactP * o.leverage / 100 / PRECISION_18 > pairInfos.maxNegativePnlOnOpenP()) {
            return IOstiumTradingCallbacks.CancelReason.PRICE_IMPACT;
        }

        // Check max leverage
        if (!withinMaxLeverage(o.pairIndex, o.leverage, o.isDayTrade, pairsStorage)) {
            return IOstiumTradingCallbacks.CancelReason.MAX_LEVERAGE;
        }

        return IOstiumTradingCallbacks.CancelReason.NONE;
    }

    function getAutomationCloseOrderCancelReason(
        IOstiumTradingStorage.LimitOrder orderType,
        IOstiumTradingStorage.Trade memory t,
        uint256 triggerPrice,
        uint256 usdcSentToTrader,
        bool isDayTradingClosed
    ) external pure returns (IOstiumTradingCallbacks.CancelReason) {
        if (orderType == IOstiumTradingStorage.LimitOrder.CLOSE_DAY_TRADE) {
            return (t.isDayTrade && isDayTradingClosed)
                ? IOstiumTradingCallbacks.CancelReason.NONE
                : IOstiumTradingCallbacks.CancelReason.CLOSE_DAY_TRADE_NOT_ALLOWED;
        } else if (orderType == IOstiumTradingStorage.LimitOrder.LIQ) {
            return usdcSentToTrader == 0
                ? IOstiumTradingCallbacks.CancelReason.NONE
                : IOstiumTradingCallbacks.CancelReason.NOT_HIT;
        } else if (orderType == IOstiumTradingStorage.LimitOrder.TP) {
            return t.tp > 0 && (t.buy ? triggerPrice >= t.tp : triggerPrice <= t.tp)
                ? IOstiumTradingCallbacks.CancelReason.NONE
                : IOstiumTradingCallbacks.CancelReason.NOT_HIT;
        } else if (orderType == IOstiumTradingStorage.LimitOrder.SL) {
            return t.sl > 0 && (t.buy ? triggerPrice <= t.sl : triggerPrice >= t.sl)
                ? IOstiumTradingCallbacks.CancelReason.NONE
                : IOstiumTradingCallbacks.CancelReason.NOT_HIT;
        }
        return IOstiumTradingCallbacks.CancelReason.NOT_HIT;
    }

    // @notice Raw decaying close surcharge for a (partial) close, denominated in notional.
    // @dev Returns the un-capped fee. The profit cap (fee <= realized gain) is applied by the
    // caller (callbacks), where the trade value is known. Surcharge is full at holdTime == 0 and
    // decays linearly to 0 at decayWindow. Disabled (returns 0) when either param is 0.
    function getRawCloseFee(
        uint256 collateralToClose,
        uint32 leverage,
        uint256 holdTime,
        uint32 closeFeeDecayWindow,
        uint32 closeFeeStartingP
    ) public pure returns (uint256) {
        if (closeFeeStartingP == 0 || closeFeeDecayWindow == 0 || holdTime >= closeFeeDecayWindow) {
            return 0;
        }
        uint256 rate = uint256(closeFeeStartingP) * (closeFeeDecayWindow - holdTime) / closeFeeDecayWindow;

        uint256 result = (collateralToClose * leverage * rate) / (1e2 * CLOSE_FEE_SCALE_FACTOR);
        return result;
    }

    // @notice Decaying close surcharge for a (partial) close, capped at the realized gain.
    // @dev Wraps getRawCloseFee (notional-based, time-decaying) and clamps the result to the
    // trade's gain so principal is never touched: a losing or break-even close pays nothing.
    function getCappedCloseFee(
        uint256 collateralToClose,
        uint32 leverage,
        uint256 holdTime,
        uint256 tradeValue,
        uint32 closeFeeDecayWindow,
        uint32 closeFeeStartingP
    ) external pure returns (uint256 closeFee) {
        closeFee = getRawCloseFee(collateralToClose, leverage, holdTime, closeFeeDecayWindow, closeFeeStartingP);
        if (closeFee == 0) {
            return 0;
        }
        uint256 gain = tradeValue > collateralToClose ? tradeValue - collateralToClose : 0;
        if (closeFee > gain) {
            closeFee = gain;
        }
    }

    function getHandleRemoveCollateralCancelReason(
        IOstiumPriceUpKeep.PriceUpKeepAnswer calldata a,
        IOstiumTradingStorage.Trade memory trade,
        IOstiumPairInfos pairInfos,
        IOstiumPairsStorage pairsStorage,
        uint32 initialLeverage
    ) external returns (IOstiumTradingCallbacks.CancelReason) {
        TradingCallbacksLib.PriceImpactResult memory result = getDynamicTradePriceImpact(
            a.price, a.ask, a.bid, false, trade, pairInfos, trade.collateral
        );

        (int256 profitP, int256 maxPnlP) = currentPercentProfit(
            trade.openPrice.toInt256(),
            result.priceAfterImpact.toInt256(),
            trade.buy,
            int32(trade.leverage),
            int32(initialLeverage)
        );

        uint32 maxLeverage = getEffectiveMaxLeverage(trade.pairIndex, trade.isDayTrade, pairsStorage);

        if (maxLeverage == 0) {
            return IOstiumTradingCallbacks.CancelReason.MAX_LEVERAGE;
        }

        (uint256 tradeValue, uint256 liqMarginValue,,) = pairInfos.getTradeValue(
            trade.trader,
            trade.pairIndex,
            trade.index,
            trade.buy,
            trade.collateral,
            trade.leverage,
            profitP,
            maxLeverage
        );

        bool isLiquidated = tradeValue < liqMarginValue;
        uint256 usdcSentToTrader = isLiquidated ? 0 : tradeValue;

        if (usdcSentToTrader == 0) {
            return IOstiumTradingCallbacks.CancelReason.UNDER_LIQUIDATION;
        }

        // Check leverage against appropriate max based on trade type (not market state)
        if (!withinMaxLeverage(trade.pairIndex, trade.leverage, trade.isDayTrade, pairsStorage)) {
            return IOstiumTradingCallbacks.CancelReason.MAX_LEVERAGE;
        }

        if (profitP == maxPnlP) {
            return IOstiumTradingCallbacks.CancelReason.GAIN_LOSS;
        }

        return IOstiumTradingCallbacks.CancelReason.NONE;
    }

    function _decayVolumeWithPade(uint256 volume, uint32 decayInterval, uint128 decayRate)
        internal
        pure
        returns (uint256 decayedVolume)
    {
        if (decayInterval == 0) {
            return volume;
        }

        uint256 decayFactor_half = uint256(decayRate) * decayInterval / 2;
        uint256 numerator = PRECISION_18 > decayFactor_half ? PRECISION_18 - decayFactor_half : 0;
        uint256 denominator = PRECISION_18 + decayFactor_half;
        uint256 decayMultiplier = numerator * PRECISION_18 / denominator;

        return uint128(uint256(volume) * decayMultiplier / PRECISION_18);
    }

    function _priceImpactFunction(
        uint256 netVolThreshold,
        uint256 priceImpactK,
        uint256 tradeSize,
        uint256 initialVol,
        uint256 midPrice,
        uint256 askPrice,
        uint256 bidPrice
    ) internal pure returns (uint256 priceImpactP) {
        uint256 spreadComponent = (askPrice - bidPrice) * PRECISION_18 * 100 / (midPrice * 2);
        uint256 dynamicComponent = 0;

        uint256 finalVol = tradeSize + initialVol;
        if (finalVol > netVolThreshold) {
            uint256 excessVol = finalVol - netVolThreshold;
            dynamicComponent = initialVol < netVolThreshold
                ? priceImpactK * excessVol * excessVol * 100 / (2 * tradeSize) / PRECISION_27
                : priceImpactK * (initialVol - netVolThreshold + tradeSize / 2) * 100 / PRECISION_27;
        }

        priceImpactP = spreadComponent + dynamicComponent;
        return priceImpactP;
    }

    function getDynamicTradePriceImpact(
        int192 price,
        int192 ask,
        int192 bid,
        bool isOpen,
        IOstiumTradingStorage.Trade memory trade,
        IOstiumPairInfos pairInfos,
        uint256 collateralValue
    ) public returns (PriceImpactResult memory) {
        uint256 priceImpactK = pairInfos.getPairPriceImpactK(trade.pairIndex);

        uint256 priceImpactP;
        uint256 priceAfterImpact;
        if (priceImpactK == 0) {
            (priceImpactP, priceAfterImpact) = _getTradePriceImpact(price, ask, bid, isOpen, trade.buy);
            return PriceImpactResult({priceImpactP: priceImpactP, priceAfterImpact: priceAfterImpact, isDynamic: false});
        }

        (uint256 netVolThreshold, uint128 decayRate,) = pairInfos.pairDynamicSpreadParams(trade.pairIndex);

        (uint256 buyVolume, uint256 sellVolume, uint32 lastUpdateTimestamp) =
            pairInfos.pairDynamicSpreadState(trade.pairIndex);

        uint32 dt = block.timestamp > lastUpdateTimestamp ? uint32(block.timestamp) - lastUpdateTimestamp : 0;
        uint128 effectiveDecayRate = _getEffectiveDecayRate(buyVolume, sellVolume, decayRate, netVolThreshold);

        uint256 initialVolume = (trade.buy == isOpen) ? buyVolume : sellVolume;
        initialVolume = _decayVolumeWithPade(initialVolume, dt, effectiveDecayRate);

        uint256 tradeNotional = collateralValue * trade.leverage * PRECISION_10;

        priceAfterImpact = uint192(price);

        priceImpactP = _priceImpactFunction(
            netVolThreshold, priceImpactK, tradeNotional, initialVolume, uint192(price), uint192(ask), uint192(bid)
        );

        if (priceImpactP > 0) {
            if (isOpen == trade.buy) {
                priceAfterImpact = priceAfterImpact * (PRECISION_18 + (priceImpactP / 100)) / PRECISION_18;
            } else {
                if (priceImpactP < 100e18) {
                    priceAfterImpact = priceAfterImpact * (PRECISION_18 - (priceImpactP / 100)) / PRECISION_18;
                } else {
                    priceAfterImpact = 0;
                    priceImpactP = 100e18;
                }
            }
        }

        return PriceImpactResult({priceImpactP: priceImpactP, priceAfterImpact: priceAfterImpact, isDynamic: true});
    }

    function calculateDecayedVolumesWithPostFeeCollateral(
        uint16 pairIndex,
        bool isOpen,
        bool isBuy,
        uint256 postFeeCollateral,
        uint32 leverage,
        IOstiumPairInfos pairInfos
    ) external returns (uint256 decayedBuyVolume, uint256 decayedSellVolume) {
        (uint256 netVolThreshold, uint128 decayRate,) = pairInfos.pairDynamicSpreadParams(pairIndex);

        (uint256 buyVolume, uint256 sellVolume, uint32 lastUpdateTimestamp) =
            pairInfos.pairDynamicSpreadState(pairIndex);

        uint32 dt = block.timestamp > lastUpdateTimestamp ? uint32(block.timestamp) - lastUpdateTimestamp : 0;

        uint128 effectiveDecayRate = _getEffectiveDecayRate(buyVolume, sellVolume, decayRate, netVolThreshold);
        decayedBuyVolume = _decayVolumeWithPade(buyVolume, dt, effectiveDecayRate);
        decayedSellVolume = _decayVolumeWithPade(sellVolume, dt, effectiveDecayRate);

        uint256 tradeNotional = postFeeCollateral * leverage * PRECISION_10;

        if (isOpen == isBuy) {
            decayedBuyVolume += tradeNotional;
        } else {
            decayedSellVolume += tradeNotional;
        }
    }

    function _getEffectiveDecayRate(uint256 buyVolume, uint256 sellVolume, uint128 decayRate, uint256 netVolThreshold)
        internal
        pure
        returns (uint128)
    {
        if (netVolThreshold == 0) {
            return decayRate * PRECISION_18 / MAX_DECAY_FACTOR;
        }
        uint256 absNetVol = buyVolume > sellVolume ? buyVolume - sellVolume : sellVolume - buyVolume;

        uint256 factor = PRECISION_18;
        if (absNetVol > netVolThreshold) {
            uint256 ratio = absNetVol * PRECISION_18 / netVolThreshold;
            factor = ratio > MAX_DECAY_FACTOR ? MAX_DECAY_FACTOR : ratio;
        }

        return uint128(decayRate * PRECISION_18 / factor);
    }

    // @dev uses the same calculations as in TadingLib.getOpenTradeRevert()
    function calculatePostFeeCollateral(
        uint256 collateral,
        uint32 leverage,
        uint16 pairIndex,
        uint32 takerFeeP,
        IOstiumPairsStorage pairsStorage,
        IOstiumTradingStorage.BuilderFee memory bf
    ) public view returns (uint256) {
        uint256 preFeeNotional = collateral * leverage / 100;

        uint256 oracleFee = pairsStorage.pairOracleFee(pairIndex);

        uint256 builderFee = 0;
        if (bf.builder != address(0) && bf.builderFee > 0) {
            builderFee = bf.builderFee * preFeeNotional / PRECISION_6 / 100;
        }
        // We only use takerFeeP no matter maker or taker
        uint256 openingFee = preFeeNotional * takerFeeP / PRECISION_6 / 100;

        uint256 totalFees = openingFee + oracleFee + builderFee;

        // @dev In very unlikely case of totalFees >= collateral this call will revert with underflow
        // the check that ensures this does not happen exists on openTrade() function
        // if one of the fee values change drastically before the upkeep, it may revert for very small values of collateral
        return collateral - totalFees;
    }

    function executeRegisterTrade(
        uint256 tradeId,
        IOstiumTradingStorage.Trade memory trade,
        uint256 latestPrice,
        IOstiumTradingStorage.BuilderFee memory bf,
        uint8 maxSl_P,
        IOstiumTradingStorage storageT,
        IOstiumPairInfos pairInfos,
        IOstiumPairsStorage pairsStorage,
        IOstiumVault vault
    )
        external
        returns (
            IOstiumTradingStorage.Trade memory,
            uint256 reward,
            uint256 vaultReward,
            uint256 oracleFee,
            uint256 builderFee
        )
    {
        uint256 tradeNotional = Math.mulDiv(trade.collateral, trade.leverage, 100, Math.Rounding.Ceil);

        // 2.1 Charge opening fee
        {
            (reward, vaultReward) =
                storageT.handleOpeningFees(trade.pairIndex, latestPrice, tradeNotional, trade.leverage, trade.buy);

            trade.collateral -= reward;

            if (vaultReward > 0) {
                storageT.transferUsdc(address(storageT), address(this), vaultReward);
                vault.distributeReward(vaultReward);
                trade.collateral -= vaultReward;
            }
        }

        oracleFee = pairsStorage.pairOracleFee(trade.pairIndex);
        storageT.handleOracleFee(oracleFee);
        trade.collateral -= oracleFee;

        if (bf.builder != address(0) && bf.builderFee > 0) {
            builderFee = bf.builderFee * tradeNotional / PRECISION_6 / 100;
            storageT.transferUsdc(address(storageT), bf.builder, builderFee);
            trade.collateral -= builderFee;
        }

        // 4. Set trade final details
        trade.index = storageT.firstEmptyTradeIndex(trade.trader, trade.pairIndex);

        trade.tp = correctTp(trade.openPrice, trade.tp, trade.leverage, trade.leverage, trade.buy);
        trade.sl = correctSl(trade.openPrice, trade.sl, trade.leverage, trade.leverage, trade.buy, maxSl_P);

        // 5. Call other contracts
        pairInfos.storeTradeInitialAccFees(tradeId, trade.trader, trade.pairIndex, trade.index, trade.buy);
        pairsStorage.updateGroupCollateral(trade.pairIndex, trade.collateral, trade.buy, true);

        // 6. Store final trade in storage contract
        uint32 currTimestamp = block.timestamp.toUint32();
        storageT.storeTrade(
            trade,
            IOstiumTradingStorage.TradeInfo(
                tradeId,
                trade.collateral * uint256(1e12) * trade.leverage / 100 * PRECISION_18 / trade.openPrice,
                trade.leverage,
                currTimestamp,
                currTimestamp,
                currTimestamp,
                false
            )
        );

        return (trade, reward, vaultReward, oracleFee, builderFee);
    }

    function executeUnregisterTrade(
        IOstiumTradingStorage.Trade memory trade,
        uint256 usdcSentToTrader,
        uint256 liquidationFee,
        uint256 collateralToClose,
        IOstiumTradingStorage storageT,
        IOstiumPairsStorage pairsStorage,
        IOstiumVault vault
    ) external {
        pairsStorage.updateGroupCollateral(trade.pairIndex, collateralToClose, trade.buy, false);

        // 3.1 Unregister trade
        storageT.unregisterTrade(trade.trader, trade.pairIndex, trade.index, collateralToClose);

        // 3 USDC vault reward
        if (liquidationFee > 0) {
            storageT.transferUsdc(address(storageT), address(this), liquidationFee);
            vault.receiveAssets(liquidationFee, trade.trader);
        }

        // 4 Take USDC from vault if winning trade
        // or send USDC to vault if losing trade
        uint256 usdcLeftInStorage = collateralToClose - liquidationFee;

        if (usdcSentToTrader > usdcLeftInStorage) {
            vault.sendAssets(usdcSentToTrader - usdcLeftInStorage, trade.trader);
            storageT.transferUsdc(address(storageT), trade.trader, usdcLeftInStorage);
        } else {
            uint256 usdcSentToVault = usdcLeftInStorage - usdcSentToTrader;
            storageT.transferUsdc(address(storageT), address(this), usdcSentToVault);
            vault.receiveAssets(usdcSentToVault, trade.trader);
            if (usdcSentToTrader > 0) storageT.transferUsdc(address(storageT), trade.trader, usdcSentToTrader);
        }
    }
}

src/OstiumTradingCallbacks.sol.content:
/// SPDX-License-Identifier: MIT
import '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import '@openzeppelin/contracts/utils/math/Math.sol';
import '@openzeppelin/contracts/utils/math/SafeCast.sol';
import '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';
import '@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol';

import './interfaces/IOstiumTradingStorage.sol';
import './interfaces/IOstiumPairInfos.sol';
import './interfaces/IOstiumRegistry.sol';
import './interfaces/IOstiumTradingCallbacks.sol';
import './interfaces/IOstiumPairsStorage.sol';

import './interfaces/IOstiumOpenPnl.sol';
import './lib/TradingCallbacksLib.sol';

pragma solidity ^0.8.24;

contract OstiumTradingCallbacks is IOstiumTradingCallbacks, Initializable {
    using Math for uint256;
    using SafeCast for uint256;
    using SafeCast for uint192;

    // Contracts (constant)
    IOstiumRegistry public registry;

    // Params (constant)
    uint64 constant PRECISION_18 = 1e18;
    uint32 constant PRECISION_6 = 1e6;
    uint32 constant CLOSE_FEE_WINDOW_MAX = 5 minutes;
    uint32 constant CLOSE_FEE_P_MAX = 100e6; // 100% PRECISION_6

    // State
    uint8 public maxSl_P; // How much % from the open price the stop loss can be set
    bool public isPaused; // Prevent opening new trades
    bool public isDone; // Prevent any interaction with the contract
    uint32 public closeFeeDecayWindow; // seconds; surcharge decays linearly to 0 over this window; 0 disables
    uint32 public closeFeeStartingP; // PRECISION_6 (%) of notional, charged at holdTime=0; 0 disables

    constructor() {
        _disableInitializers();
    }

    function initialize(IOstiumRegistry _registry) external initializer {
        if (address(_registry) == address(0)) {
            revert WrongParams();
        }

        registry = _registry;
        _setMaxSl_P(85);
    }

    // Modifiers
    modifier onlyGov() {
        isGov();
        _;
    }

    modifier onlyManager() {
        isManager();
        _;
    }

    modifier notDone() {
        isNotDone();
        _;
    }

    modifier onlyTrading() {
        isTrading();
        _;
    }

    function isGov() private view {
        if (msg.sender != registry.gov()) {
            revert NotGov(msg.sender);
        }
    }

    function isManager() private view {
        if (msg.sender != registry.manager()) {
            revert NotManager(msg.sender);
        }
    }

    function isPriceUpKeep(uint16 pairIndex) private view {
        string memory priceUpkeepType =
            IOstiumPairsStorage(registry.getContractAddress('pairsStorage')).oracle(pairIndex);
        if (msg.sender != registry.getContractAddress(bytes32(abi.encodePacked(priceUpkeepType, 'PriceUpkeep')))) {
            revert NotPriceUpKeep(msg.sender);
        }
    }

    function isNotDone() private view {
        if (isDone) {
            revert IsDone();
        }
    }

    function isTrading() private view {
        if (msg.sender != registry.getContractAddress('trading')) {
            revert NotTrading(msg.sender);
        }
    }

    function getContracts()
        private
        view
        returns (IOstiumTradingStorage storageT, IOstiumPairInfos pairInfos, IOstiumPairsStorage pairsStorage)
    {
        storageT = IOstiumTradingStorage(registry.getContractAddress('tradingStorage'));
        pairInfos = IOstiumPairInfos(registry.getContractAddress('pairInfos'));
        pairsStorage = IOstiumPairsStorage(registry.getContractAddress('pairsStorage'));
    }

    function _updateDynamicSpreadVolumes(
        uint16 pairIndex,
        bool isOpen,
        bool isBuy,
        uint256 collateral,
        uint32 leverage,
        IOstiumPairInfos pairInfos
    ) private {
        (uint256 decayedBuyVolume, uint256 decayedSellVolume) = TradingCallbacksLib.calculateDecayedVolumesWithPostFeeCollateral(
            pairIndex, isOpen, isBuy, collateral, leverage, pairInfos
        );
        pairInfos.updateDynamicSpreadState(pairIndex, decayedBuyVolume, decayedSellVolume);
    }

    function setMaxSl_P(uint256 _maxSl_P) external onlyGov {
        if (_maxSl_P == 0 || _maxSl_P > 100) {
            revert WrongParams();
        }
        _setMaxSl_P(_maxSl_P);
    }

    function _setMaxSl_P(uint256 _maxSl_P) private {
        maxSl_P = _maxSl_P.toUint8();
        emit MaxSlPUpdated(_maxSl_P);
    }

    function setCloseFeeParams(uint32 _decayWindow, uint32 _startingP) external onlyGov {
        if (CLOSE_FEE_WINDOW_MAX < _decayWindow || CLOSE_FEE_P_MAX < _startingP) {
            revert WrongParams();
        }
        closeFeeDecayWindow = _decayWindow;
        closeFeeStartingP = _startingP;
        emit CloseFeeParamsUpdated(closeFeeDecayWindow, closeFeeStartingP);
    }

    function setVaultMaxAllowance() external onlyGov {
        IERC20 usdc = IERC20(IOstiumTradingStorage(registry.getContractAddress('tradingStorage')).usdc());
        SafeERC20.forceApprove(usdc, registry.getContractAddress('vault'), type(uint256).max);
    }

    function unsetVaultMaxAllowance(address _oldVault) external onlyGov {
        IERC20 usdc = IERC20(IOstiumTradingStorage(registry.getContractAddress('tradingStorage')).usdc());
        SafeERC20.forceApprove(usdc, _oldVault, 0);
    }

    function pause() external onlyManager {
        isPaused = !isPaused;

        emit Paused(isPaused);
    }

    function done() external onlyGov {
        isDone = !isDone;

        emit Done(isDone);
    }

    function openTradeMarketCallback(IOstiumPriceUpKeep.PriceUpKeepAnswer calldata a) external notDone {
        (IOstiumTradingStorage storageT, IOstiumPairInfos pairInfos, IOstiumPairsStorage pairsStorage) = getContracts();
        (uint256 _block, uint256 wantedPrice, uint256 slippageP, IOstiumTradingStorage.Trade memory trade,) =
            storageT.reqID_pendingMarketOrder(a.orderId);
        IOstiumTradingStorage.BuilderFee memory bf = storageT.getBuilderData(trade.trader, trade.pairIndex, a.orderId);

        if (_block == 0) {
            return;
        }

        isPriceUpKeep(trade.pairIndex);

        TradingCallbacksLib.PriceImpactResult memory result;
        CancelReason cancelReason;

        if (a.price <= 0 || a.bid <= 0 || a.ask <= 0) {
            cancelReason = CancelReason.MARKET_CLOSED;
        } else if (trade.isDayTrade && a.isDayTradingClosed) {
            cancelReason = CancelReason.DAY_TRADE_NOT_ALLOWED;
        } else {
            (, uint32 takerFeeP,,,,) = pairInfos.pairOpeningFees(trade.pairIndex);
            uint256 calculatedPostFeeCollateral = TradingCallbacksLib.calculatePostFeeCollateral(
                trade.collateral, trade.leverage, trade.pairIndex, takerFeeP, pairsStorage, bf
            );

            result = TradingCallbacksLib.getDynamicTradePriceImpact(
                a.price, int192(a.ask), int192(a.bid), true, trade, pairInfos, calculatedPostFeeCollateral
            );

            trade.openPrice = result.priceAfterImpact.toUint192();

            cancelReason = TradingCallbacksLib.getOpenTradeMarketCancelReason(
                isPaused,
                wantedPrice,
                slippageP,
                uint192(a.price),
                trade,
                result.priceImpactP,
                IOstiumPairInfos(registry.getContractAddress('pairInfos')),
                pairsStorage,
                storageT
            );
        }

        if (cancelReason == CancelReason.NONE) {
            trade = registerTrade(a.orderId, trade, uint192(a.price), bf);

            if (result.isDynamic) {
                _updateDynamicSpreadVolumes(
                    trade.pairIndex, true, trade.buy, trade.collateral, trade.leverage, pairInfos
                );
            }
            uint256 tradeNotional = storageT.getOpenTradeInfo(trade.trader, trade.pairIndex, trade.index).oiNotional;
            IOstiumOpenPnl(registry.getContractAddress('openPnl'))
                .updateAccTotalPnl(a.price, trade.openPrice, 0, tradeNotional, trade.pairIndex, trade.buy, true);
            IOstiumOpenPnl(registry.getContractAddress('openPnl')).updateAccClosedRollover(trade, 0);
            emit MarketOpenExecuted(a.orderId, trade, result.priceImpactP, tradeNotional);
        } else {
            uint256 oracleFee = pairsStorage.pairOracleFee(trade.pairIndex);
            if (trade.collateral > oracleFee) {
                storageT.transferUsdc(address(storageT), trade.trader, trade.collateral - oracleFee);
            } else {
                oracleFee = trade.collateral;
            }
            storageT.handleOracleFee(oracleFee);

            emit OracleFeeCharged(a.orderId, trade.trader, oracleFee);
            emit MarketOpenCanceled(a.orderId, trade.trader, trade.pairIndex, cancelReason);
        }
        storageT.unregisterPendingMarketOrder(a.orderId, true);
    }

    function closeTradeMarketCallback(IOstiumPriceUpKeep.PriceUpKeepAnswer calldata a) external notDone {
        (IOstiumTradingStorage storageT, IOstiumPairInfos pairInfos,) = getContracts();
        (
            uint256 _block,
            uint256 wantedPrice,
            uint256 slippageP,
            IOstiumTradingStorage.Trade memory trade,
            uint16 closePercentage
        ) = storageT.reqID_pendingMarketOrder(a.orderId);

        if (_block == 0) {
            return;
        }

        isPriceUpKeep(trade.pairIndex);

        IOstiumTradingStorage.Trade memory t = storageT.getOpenTrade(trade.trader, trade.pairIndex, trade.index);

        CancelReason cancelReason = t.leverage == 0
            ? CancelReason.NO_TRADE
            : ((a.price <= 0 || a.bid <= 0 || a.ask <= 0) ? CancelReason.MARKET_CLOSED : CancelReason.NONE);

        IOstiumTradingStorage.TradeInfo memory i = storageT.getOpenTradeInfo(t.trader, t.pairIndex, t.index);

        // Validate tradeId matches to prevent execution on replaced trades
        // Skip validation if storedTradeId == 0 (legacy order from before upgrade)
        if (cancelReason == CancelReason.NONE) {
            uint256 storedTradeId = storageT.pendingMarketCloseTradeIds(a.orderId);
            if (storedTradeId != 0 && i.tradeId != storedTradeId) {
                cancelReason = CancelReason.WRONG_TRADE;
            }
        }

        if (cancelReason != CancelReason.NO_TRADE) {
            if (cancelReason == CancelReason.NONE) {
                uint256 collateralToClose = t.collateral * closePercentage / 100e2;
                IOstiumPairsStorage pairsStorage = IOstiumPairsStorage(registry.getContractAddress('pairsStorage'));
                uint32 maxLeverage =
                    TradingCallbacksLib.getEffectiveMaxLeverage(t.pairIndex, t.isDayTrade, pairsStorage);
                (
                    TradingCallbacksLib.TradeValueResult memory tvResult,
                    TradingCallbacksLib.PriceImpactResult memory piResult
                ) = TradingCallbacksLib.getTradeAndPriceData(
                    a, t, pairInfos, i.initialLeverage, maxLeverage, collateralToClose, true
                );

                uint256 maxSlippage = (wantedPrice * slippageP) / 100 / 100;

                if (t.buy
                        ? piResult.priceAfterImpact < wantedPrice - maxSlippage
                        : piResult.priceAfterImpact > wantedPrice + maxSlippage) {
                    cancelReason = IOstiumTradingCallbacks.CancelReason.SLIPPAGE;
                } else {
                    if (piResult.isDynamic) {
                        _updateDynamicSpreadVolumes(t.pairIndex, false, t.buy, collateralToClose, t.leverage, pairInfos);
                    }

                    bool isLiquidated = tvResult.tradeValue < tvResult.liqMarginValue;

                    (tvResult.profitP,) = TradingCallbacksLib.currentPercentProfit(
                        t.openPrice.toInt256(),
                        piResult.priceAfterImpact.toInt256(),
                        t.buy,
                        int32(t.leverage),
                        int32(i.initialLeverage)
                    );
                    tvResult.tradeValue = pairInfos.getTradeValuePure(
                        collateralToClose, tvResult.profitP, tvResult.rolloverFees, tvResult.fundingFees
                    );

                    IOstiumOpenPnl(registry.getContractAddress('openPnl'))
                        .updateAccTotalPnl(
                            a.price,
                            t.openPrice,
                            piResult.priceAfterImpact,
                            i.oiNotional * collateralToClose / t.collateral, // mirrors unregisterTrade to avoid accNetOiUnits drift
                            t.pairIndex,
                            t.buy,
                            false
                        );
                    IOstiumOpenPnl(registry.getContractAddress('openPnl')).updateAccClosedRollover(t, closePercentage);

                    uint256 liquidationFee = isLiquidated ? tvResult.tradeValue : 0;

                    // Decaying close surcharge: claw back a fraction of the realized gain on a fast
                    // close. Skipped on liquidation; capped at the gain so principal is never touched.
                    // The deducted amount flows to the vault via unregisterTrade's settlement math.
                    if (!isLiquidated) {
                        uint256 closeFee = TradingCallbacksLib.getCappedCloseFee(
                            collateralToClose,
                            t.leverage,
                            block.timestamp - i.createdAt,
                            tvResult.tradeValue,
                            closeFeeDecayWindow,
                            closeFeeStartingP
                        );
                        if (closeFee > 0) {
                            tvResult.tradeValue -= closeFee;
                            emit CloseFeeCharged(a.orderId, i.tradeId, t.trader, closeFee);
                        }
                    }

                    unregisterTrade(
                        a.orderId,
                        i.tradeId,
                        t,
                        isLiquidated ? 0 : tvResult.tradeValue,
                        liquidationFee,
                        collateralToClose
                    );

                    emit FeesChargedV2(a.orderId, i.tradeId, t.trader, tvResult.rolloverFees, tvResult.fundingFees);
                    emit MarketCloseExecutedV2(
                        a.orderId,
                        i.tradeId,
                        piResult.priceAfterImpact,
                        piResult.priceImpactP,
                        tvResult.profitP,
                        tvResult.tradeValue,
                        closePercentage
                    );

                    if (closePercentage == 100e2) {
                        // Full close and successfully closed - refund the oracle fee
                        uint256 oracleFee = pairsStorage.pairOracleFee(t.pairIndex);
                        storageT.refundOracleFee(oracleFee);
                        storageT.transferUsdc(address(storageT), t.trader, oracleFee);
                        emit OracleFeeRefunded(i.tradeId, t.trader, t.pairIndex, oracleFee);
                    }
                }
            }
        }

        if (cancelReason != CancelReason.NONE) {
            emit MarketCloseCanceled(a.orderId, i.tradeId, trade.trader, trade.pairIndex, trade.index, cancelReason);
        }

        storageT.clearDeprecatedBeingMarketClosed(trade.trader, trade.pairIndex, trade.index);
        if (cancelReason != CancelReason.WRONG_TRADE) {
            storageT.unregisterTrigger(
                trade.trader, trade.pairIndex, trade.index, IOstiumTradingStorage.LimitOrder.PENDING_CLOSE
            );
        }
        storageT.unregisterPendingMarketOrder(a.orderId, false);
    }

    function executeAutomationOpenOrderCallback(IOstiumPriceUpKeep.PriceUpKeepAnswer calldata a) external notDone {
        (IOstiumTradingStorage storageT, IOstiumPairInfos pairInfos, IOstiumPairsStorage pairsStorage) = getContracts();

        CancelReason cancelReason;
        (address trader, uint16 pairIndex, uint8 index,,) = storageT.reqID_pendingAutomationOrder(a.orderId);

        if (trader == address(0)) {
            return;
        }

        isPriceUpKeep(pairIndex);

        cancelReason = isPaused
            ? CancelReason.PAUSED
            : ((a.price <= 0 || a.bid <= 0 || a.ask <= 0)
                    ? CancelReason.MARKET_CLOSED
                    : !storageT.hasOpenLimitOrder(trader, pairIndex, index) ? CancelReason.NO_TRADE : CancelReason.NONE);

        IOstiumTradingStorage.OpenLimitOrder memory o;
        IOstiumTradingStorage.BuilderFee memory bf;
        if (cancelReason == CancelReason.NONE) {
            o = storageT.getOpenLimitOrder(trader, pairIndex, index);
            bf = storageT.getBuilderData(trader, pairIndex, index);

            // Validate limitOrderId matches to prevent execution on replaced limit orders
            // The stored ID is in the tradeId field of PendingAutomationOrder (repurposed for OPEN orders)
            (,,,, uint256 storedLimitOrderId) = storageT.reqID_pendingAutomationOrder(a.orderId);
            uint256 currentLimitOrderId = storageT.limitOrderIds(trader, pairIndex, index);
            // Skip validation if storedLimitOrderId == 0 (legacy order from before upgrade)
            // or if currentLimitOrderId == 0 (legacy limit order from before upgrade)
            if (storedLimitOrderId != 0 && currentLimitOrderId != 0 && currentLimitOrderId != storedLimitOrderId) {
                cancelReason = CancelReason.WRONG_TRADE;
            } else if (o.isDayTrade && a.isDayTradingClosed) {
                cancelReason = CancelReason.DAY_TRADE_NOT_ALLOWED;
            }
        }

        if (cancelReason == CancelReason.NONE) {
            IOstiumTradingStorage.Trade memory tempTrade = IOstiumTradingStorage.Trade(
                o.collateral, 0, o.tp, o.sl, o.trader, o.leverage, o.pairIndex, 0, o.buy, o.isDayTrade
            );
            (, uint32 takerFeeP,,,,) = pairInfos.pairOpeningFees(pairIndex);
            uint256 calculatedPostFeeCollateral = TradingCallbacksLib.calculatePostFeeCollateral(
                o.collateral, o.leverage, pairIndex, takerFeeP, pairsStorage, bf
            );

            TradingCallbacksLib.PriceImpactResult memory result = TradingCallbacksLib.getDynamicTradePriceImpact(
                a.price, a.ask, a.bid, true, tempTrade, pairInfos, calculatedPostFeeCollateral
            );

            cancelReason = TradingCallbacksLib.getAutomationOpenOrderCancelReason(
                o, result.priceAfterImpact, uint192(a.price), result.priceImpactP, pairInfos, pairsStorage, storageT
            );

            if (cancelReason == CancelReason.NONE) {
                IOstiumTradingStorage.Trade memory trade = registerTrade(
                    a.orderId,
                    IOstiumTradingStorage.Trade(
                        o.collateral,
                        result.priceAfterImpact.toUint192(),
                        o.tp,
                        o.sl,
                        o.trader,
                        o.leverage,
                        o.pairIndex,
                        0,
                        o.buy,
                        o.isDayTrade
                    ),
                    uint192(a.price),
                    bf
                );

                if (result.isDynamic) {
                    _updateDynamicSpreadVolumes(
                        trade.pairIndex, true, trade.buy, trade.collateral, trade.leverage, pairInfos
                    );
                }
                uint256 tradeNotional = storageT.getOpenTradeInfo(trade.trader, trade.pairIndex, trade.index).oiNotional;

                IOstiumOpenPnl(registry.getContractAddress('openPnl'))
                    .updateAccTotalPnl(a.price, trade.openPrice, 0, tradeNotional, trade.pairIndex, trade.buy, true);
                IOstiumOpenPnl(registry.getContractAddress('openPnl')).updateAccClosedRollover(trade, 0);
                storageT.unregisterOpenLimitOrder(o.trader, o.pairIndex, o.index);
                emit LimitOpenExecuted(a.orderId, o.index, trade, result.priceImpactP, tradeNotional);
            }
        }

        if (cancelReason != CancelReason.NONE) {
            emit AutomationOpenOrderCanceled(a.orderId, trader, pairIndex, cancelReason);
        }
        if (cancelReason != CancelReason.WRONG_TRADE) {
            storageT.unregisterTrigger(trader, pairIndex, index, IOstiumTradingStorage.LimitOrder.OPEN);
        }
        storageT.unregisterPendingAutomationOrder(a.orderId);
    }

    function executeAutomationCloseOrderCallback(IOstiumPriceUpKeep.PriceUpKeepAnswer calldata a) external notDone {
        (IOstiumTradingStorage storageT, IOstiumPairInfos pairInfos,) = getContracts();

        IOstiumTradingStorage.LimitOrder orderType;
        IOstiumTradingStorage.Trade memory t;

        (
            address trader,
            uint16 pairIndex,
            uint8 index,
            IOstiumTradingStorage.LimitOrder _orderType,
            uint256 storedTradeId
        ) = storageT.reqID_pendingAutomationOrder(a.orderId);

        if (trader == address(0)) {
            return;
        }

        isPriceUpKeep(pairIndex);
        t = storageT.getOpenTrade(trader, pairIndex, index);
        orderType = _orderType;

        CancelReason cancelReason = (a.price <= 0 || a.bid <= 0 || a.ask <= 0)
            ? CancelReason.MARKET_CLOSED
            : (t.leverage == 0 ? CancelReason.NO_TRADE : CancelReason.NONE);

        IOstiumTradingStorage.TradeInfo memory i = storageT.getOpenTradeInfo(t.trader, t.pairIndex, t.index);

        // Validate tradeId matches to prevent execution on replaced trades
        // Skip validation if storedTradeId == 0 (legacy order from before upgrade)
        if (cancelReason == CancelReason.NONE && storedTradeId != 0 && i.tradeId != storedTradeId) {
            cancelReason = CancelReason.WRONG_TRADE;
        }

        if (cancelReason == CancelReason.NONE) {
            bool isMarketPrice =
                orderType == IOstiumTradingStorage.LimitOrder.LIQ || orderType == IOstiumTradingStorage.LimitOrder.SL;

            IOstiumPairsStorage pairsStorage = IOstiumPairsStorage(registry.getContractAddress('pairsStorage'));
            uint32 maxLeverage = TradingCallbacksLib.getEffectiveMaxLeverage(t.pairIndex, t.isDayTrade, pairsStorage);
            (
                TradingCallbacksLib.TradeValueResult memory tvResult,
                TradingCallbacksLib.PriceImpactResult memory piResult
            ) = TradingCallbacksLib.getTradeAndPriceData(
                a, t, pairInfos, i.initialLeverage, maxLeverage, t.collateral, isMarketPrice
            );

            bool isLiquidated = tvResult.tradeValue < tvResult.liqMarginValue;

            cancelReason = TradingCallbacksLib.getAutomationCloseOrderCancelReason(
                orderType,
                t,
                isMarketPrice ? uint192(a.price) : piResult.priceAfterImpact,
                isLiquidated ? 0 : tvResult.tradeValue,
                a.isDayTradingClosed
            );

            if (cancelReason == CancelReason.NONE) {
                if (isMarketPrice) {
                    (tvResult.profitP,) = TradingCallbacksLib.currentPercentProfit(
                        t.openPrice.toInt256(),
                        piResult.priceAfterImpact.toInt256(),
                        t.buy,
                        int32(t.leverage),
                        int32(i.initialLeverage)
                    );
                    tvResult.tradeValue = pairInfos.getTradeValuePure(
                        t.collateral, tvResult.profitP, tvResult.rolloverFees, tvResult.fundingFees
                    );

                    isLiquidated = tvResult.tradeValue < tvResult.liqMarginValue;
                }

                if (piResult.isDynamic) {
                    _updateDynamicSpreadVolumes(t.pairIndex, false, t.buy, t.collateral, t.leverage, pairInfos);
                }

                IOstiumOpenPnl(registry.getContractAddress('openPnl'))
                    .updateAccTotalPnl(
                        a.price, t.openPrice, piResult.priceAfterImpact, i.oiNotional, t.pairIndex, t.buy, false
                    );
                IOstiumOpenPnl(registry.getContractAddress('openPnl')).updateAccClosedRollover(t, 100e2);

                uint256 liquidationFee = isLiquidated ? tvResult.tradeValue : 0;

                // Decaying close surcharge: same rule as market close, applied to TP/SL exits so they
                // cannot be used to dodge the fee. Gated on hold time and capped at the realized gain,
                // so a genuine (losing) stop-loss pays nothing.
                if (!isLiquidated) {
                    uint256 closeFee = TradingCallbacksLib.getCappedCloseFee(
                        t.collateral,
                        t.leverage,
                        block.timestamp - i.createdAt,
                        tvResult.tradeValue,
                        closeFeeDecayWindow,
                        closeFeeStartingP
                    );
                    if (closeFee > 0) {
                        tvResult.tradeValue -= closeFee;
                        emit CloseFeeCharged(a.orderId, i.tradeId, t.trader, closeFee);
                    }
                }

                unregisterTrade(
                    a.orderId, i.tradeId, t, isLiquidated ? 0 : tvResult.tradeValue, liquidationFee, t.collateral
                );

                emit FeesChargedV2(a.orderId, i.tradeId, t.trader, tvResult.rolloverFees, tvResult.fundingFees);
                emit LimitCloseExecuted(
                    a.orderId,
                    i.tradeId,
                    isLiquidated ? IOstiumTradingStorage.LimitOrder.LIQ : orderType,
                    piResult.priceAfterImpact,
                    piResult.priceImpactP,
                    tvResult.profitP,
                    isLiquidated ? 0 : tvResult.tradeValue
                );
            }
        }

        if (cancelReason != CancelReason.NONE) {
            emit AutomationCloseOrderCanceled(a.orderId, i.tradeId, t.trader, t.pairIndex, orderType, cancelReason);
        }

        if (cancelReason != CancelReason.WRONG_TRADE) {
            storageT.unregisterTrigger(t.trader, t.pairIndex, t.index, orderType);
        }
        storageT.unregisterPendingAutomationOrder(a.orderId);
    }

    function registerTrade(
        uint256 tradeId,
        IOstiumTradingStorage.Trade memory trade,
        uint256 latestPrice,
        IOstiumTradingStorage.BuilderFee memory bf
    ) private returns (IOstiumTradingStorage.Trade memory) {
        (IOstiumTradingStorage storageT, IOstiumPairInfos pairInfos, IOstiumPairsStorage pairsStorage) = getContracts();

        uint256 reward;
        uint256 vaultReward;
        uint256 oracleFee;
        uint256 builderFee;

        (trade, reward, vaultReward, oracleFee, builderFee) = TradingCallbacksLib.executeRegisterTrade(
            tradeId,
            trade,
            latestPrice,
            bf,
            maxSl_P,
            storageT,
            pairInfos,
            pairsStorage,
            IOstiumVault(registry.getContractAddress('vault'))
        );

        emit DevFeeCharged(tradeId, trade.trader, reward);
        if (vaultReward > 0) {
            emit VaultOpeningFeeCharged(tradeId, trade.trader, vaultReward);
        }
        emit OracleFeeCharged(tradeId, trade.trader, oracleFee);
        if (builderFee > 0) {
            emit BuilderFeeCharged(tradeId, trade.trader, bf.builder, builderFee);
        }

        return trade;
    }

    function unregisterTrade(
        uint256 orderId,
        uint256 tradeId,
        IOstiumTradingStorage.Trade memory trade,
        uint256 usdcSentToTrader,
        uint256 liquidationFee, // PRECISION_6
        uint256 collateralToClose // PRECISION_6
    ) private {
        (IOstiumTradingStorage storageT,, IOstiumPairsStorage pairsStorage) = getContracts();

        TradingCallbacksLib.executeUnregisterTrade(
            trade,
            usdcSentToTrader,
            liquidationFee,
            collateralToClose,
            storageT,
            pairsStorage,
            IOstiumVault(registry.getContractAddress('vault'))
        );

        if (liquidationFee > 0) {
            emit VaultLiqFeeCharged(orderId, tradeId, trade.trader, liquidationFee);
        }
    }

    function handleRemoveCollateral(IOstiumPriceUpKeep.PriceUpKeepAnswer calldata a) external notDone {
        (IOstiumTradingStorage storageT, IOstiumPairInfos pairInfos, IOstiumPairsStorage pairsStorage) = getContracts();

        IOstiumTradingStorage.PendingRemoveCollateral memory request = storageT.getPendingRemoveCollateral(a.orderId);

        if (request.trader == address(0)) {
            return;
        }

        isPriceUpKeep(request.pairIndex);

        IOstiumTradingStorage.Trade memory trade =
            storageT.getOpenTrade(request.trader, request.pairIndex, request.index);

        IOstiumTradingStorage.TradeInfo memory tradeInfo =
            storageT.getOpenTradeInfo(request.trader, request.pairIndex, request.index);

        CancelReason cancelReason;

        if (isPaused) {
            cancelReason = CancelReason.PAUSED;
        } else if (trade.leverage == 0) {
            cancelReason = CancelReason.NO_TRADE;
        } else if (a.price <= 0 || a.bid <= 0 || a.ask <= 0) {
            cancelReason = CancelReason.MARKET_CLOSED;
        } else if (request.tradeId != 0 && tradeInfo.tradeId != request.tradeId) {
            // Validate tradeId matches to prevent execution on replaced trades
            // Skip validation if request.tradeId == 0 (legacy order from before upgrade)
            cancelReason = CancelReason.WRONG_TRADE;
        } else if (trade.collateral <= request.removeAmount) {
            // Check there's enough collateral to remove to prevents division by zero or underflow when collateral was reduced by other operations
            cancelReason = CancelReason.NOT_HIT;
        } else {
            // Calculate new leverage and position details
            uint256 tradeSize = trade.collateral.mulDiv(trade.leverage, 100, Math.Rounding.Ceil);
            trade.collateral -= request.removeAmount;
            trade.leverage = (tradeSize * PRECISION_6 / trade.collateral / 1e4).toUint32();

            if (trade.isDayTrade && a.isDayTradingClosed) {
                cancelReason = CancelReason.DAY_TRADE_NOT_ALLOWED;
            } else {
                cancelReason = TradingCallbacksLib.getHandleRemoveCollateralCancelReason(
                    a, trade, pairInfos, pairsStorage, tradeInfo.initialLeverage
                );
            }
        }

        if (cancelReason == CancelReason.NONE) {
            trade.tp = TradingCallbacksLib.correctTp(
                trade.openPrice, trade.tp, trade.leverage, tradeInfo.initialLeverage, trade.buy
            );
            trade.sl = TradingCallbacksLib.correctToNullSl(
                trade.openPrice, trade.sl, trade.leverage, tradeInfo.initialLeverage, trade.buy, maxSl_P
            );

            storageT.transferUsdc(address(storageT), request.trader, request.removeAmount);
            storageT.updateTrade(trade);
            pairsStorage.updateGroupCollateral(trade.pairIndex, request.removeAmount, trade.buy, false);

            emit RemoveCollateralExecuted(
                a.orderId,
                tradeInfo.tradeId,
                request.trader,
                request.pairIndex,
                request.removeAmount,
                trade.leverage,
                trade.tp,
                trade.sl
            );
        } else {
            emit RemoveCollateralRejected(
                a.orderId, tradeInfo.tradeId, request.trader, request.pairIndex, request.removeAmount, cancelReason
            );
        }

        storageT.unregisterPendingRemoveCollateral(a.orderId);
        if (cancelReason != CancelReason.WRONG_TRADE) {
            storageT.unregisterTrigger(
                request.trader, request.pairIndex, request.index, IOstiumTradingStorage.LimitOrder.REMOVE_COLLATERAL
            );
        }
    }
}
